pub fn encode(message: Vec<char>) -> Vec<char> {
    fn swap_case(c: char) -> char {
        if c.is_ascii_lowercase() {
            c.to_ascii_uppercase()
        } else {
            c.to_ascii_lowercase()
        }
    }

    fn map_vowel(c: char) -> Option<char> {
        match c {
            'a' => Some('c'),
            'e' => Some('g'),
            'i' => Some('k'),
            'o' => Some('q'),
            'u' => Some('w'),
            'A' => Some('C'),
            'E' => Some('G'),
            'I' => Some('K'),
            'O' => Some('Q'),
            'U' => Some('W'),
            _ => None,
        }
    }

    let mut result = Vec::with_capacity(message.len());
    for ch in message {
        if ch == ' ' {
            result.push(' ');
        } else if let Some(mapped) = map_vowel(ch) {
            result.push(swap_case(mapped));
        } else {
            // consonant letter
            result.push(swap_case(ch));
        }
    }
    result
}